CREATE TABLE ibexa_url_alias (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, destination_url CLOB NOT NULL, forward_to_id INTEGER DEFAULT 0 NOT NULL, is_imported INTEGER DEFAULT 0 NOT NULL, is_internal INTEGER DEFAULT 1 NOT NULL, is_wildcard INTEGER DEFAULT 0 NOT NULL, source_md5 VARCHAR(32) DEFAULT NULL, source_url CLOB NOT NULL);
